package com.mfrp.plens.service.evaluation;
import com.mfrp.plens.config.CohortCriteria;import com.mfrp.plens.model.ProjectSubmission;import org.springframework.stereotype.Service;import java.util.*;import java.util.stream.*;
@Service public class RuleBasedEvaluationService { public int alignment(ProjectSubmission s){String text=text(s);long matches=CohortCriteria.KEYWORDS.stream().filter(text::contains).count();int documentation=s.getDocumentationLink()==null||s.getDocumentationLink().isBlank()?0:10;return Math.min(100,20+(int)matches*14+documentation);} public int overlap(ProjectSubmission candidate,List<ProjectSubmission> existing){return existing.stream().filter(item->!item.getPodName().equalsIgnoreCase(candidate.getPodName())).mapToInt(item->similarity(text(candidate),text(item))).max().orElse(0);} private int similarity(String left,String right){Set<String>a=words(left),b=words(right),union=new HashSet<>(a);union.addAll(b);a.retainAll(b);return union.isEmpty()?0:(int)Math.round(100d*a.size()/union.size());} private Set<String> words(String value){return Arrays.stream(value.split("[^a-z0-9]+",-1)).filter(word->word.length()>2).collect(Collectors.toSet());} private String text(ProjectSubmission s){return (s.getTitle()+" "+s.getProblemStatement()+" "+s.getObjectives()+" "+s.getTechnologyStack()).toLowerCase();} }
